(function () {
  var slug = function (s) { return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40); };
  var VERB = /\s(raises?|raised|lands?|secures?|closes?|bags|nabs|gets|picks up|scores|snaps up|completes)\s/i;
  var REGULATED = /(fintech|bank|insurance|health|medical|pharma|biotech|clinical|therapeutic|drone|airship|defen[cs]e|weapon|\brna\b|diagnos)/i;
  var STARTUP = /(seed|pre-seed|series [a-c]|angel|accelerator)/i;
  var out = [];
  var seen = {};
  $input.all().forEach(function (i) {
    var title = String(i.title || "").trim();
    var link = String(i.link || i.url || "");
    if (!title || /sponsored/i.test(title) || !/^https?:\/\//.test(link)) return;
    var m = title.match(VERB);
    if (!m) return;
    var org = title.slice(0, m.index).trim()
      .replace(/^.*?-based\s+/i, "")
      .replace(/^[A-Za-z .]+?[’']s\s+/, "")
      .replace(/^((profitable|french|german|spanish|british|dutch|swiss|nordic|european|scale-up|startup|company|firm)\s+)+/i, "")
      .trim();
    if (!org || org.split(/\s+/).length > 4) return;
    if (/\bfund\b/i.test(title) || /(capital|ventures?|partners|invest)/i.test(org)) return;
    var id = "src-" + slug(org);
    if (seen[id]) return;
    seen[id] = true;
    var date = i.pubDate || i.published || i.date || "";
    var blob = title + " " + String(i.description || "").replace(/<[^>]+>/g, " ").slice(0, 600) + " " + (Array.isArray(i.categories) ? i.categories.join(" ") : "");
    var startup = STARTUP.test(blob);
    out.push({
      lead_id: id, org: org, website: "", country: "", stage: startup ? (blob.match(STARTUP)[1] || "").toLowerCase() : "", needs_review: "true",
      hook: title, hook_source_url: link, hook_date: date, funding_date: startup ? date : "",
      audience: startup ? "startups" : "companies", status: "sourced", channel: "", handle: "", name: "", title: "",
      consent_basis: "", region: "", regulated: String(REGULATED.test(blob)),
      employees: "", funds_evidence: "", tags: Array.isArray(i.categories) ? i.categories.slice(0, 6).join(" ") : "", score: "", source: "public_rss"
    });
  });
  return out;
})()
